#!/usr/bin/env python3
"""Produce a stock-desk reconciliation receipt for one local JSON case."""

from __future__ import annotations

import json
import os
import sys
import tempfile
from typing import Any, Dict, List

EVENT_FIELDS = {"id", "type", "sku", "quantity"}
EVENT_TYPES = {"receipt", "ship", "reserve"}


def _receipt(case_id: str, status: str, issue: str,
             on_hand: Dict[str, int] | None = None,
             available: Dict[str, int] | None = None) -> Dict[str, Any]:
    return {
        "case_id": case_id,
        "status": status,
        "on_hand": on_hand or {},
        "available": available or {},
        "issue": issue,
        "action_performed": False,
    }


def _is_nonnegative_integer(value: Any) -> bool:
    return type(value) is int and value >= 0


def reconcile(case: Any) -> Dict[str, Any]:
    """Reconcile one parsed case without mutating it or applying stock changes."""
    if not isinstance(case, dict):
        return _receipt("", "needs_review", "invalid")
    raw_case_id = case.get("case_id")
    case_id = raw_case_id if isinstance(raw_case_id, str) else ""
    if "opening" not in case or "events" not in case:
        return _receipt(case_id, "needs_input", "missing")

    opening, events = case["opening"], case["events"]
    if not isinstance(raw_case_id, str) or not raw_case_id:
        return _receipt(case_id, "needs_review", "invalid")
    if not isinstance(opening, dict) or not isinstance(events, list):
        return _receipt(case_id, "needs_review", "invalid")
    for sku, quantity in opening.items():
        if not isinstance(sku, str) or not sku or not _is_nonnegative_integer(quantity):
            return _receipt(case_id, "needs_review", "invalid")

    unique_events: List[Dict[str, Any]] = []
    by_id: Dict[str, Dict[str, Any]] = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != EVENT_FIELDS:
            return _receipt(case_id, "needs_review", "invalid")
        event_id, event_type = event["id"], event["type"]
        sku, quantity = event["sku"], event["quantity"]
        if not isinstance(event_id, str) or not event_id:
            return _receipt(case_id, "needs_review", "invalid")
        if not isinstance(event_type, str) or event_type not in EVENT_TYPES:
            return _receipt(case_id, "needs_review", "invalid")
        if not isinstance(sku, str) or not sku or sku not in opening:
            return _receipt(case_id, "needs_review", "invalid")
        if not _is_nonnegative_integer(quantity):
            return _receipt(case_id, "needs_review", "invalid")
        previous = by_id.get(event_id)
        if previous is not None:
            if previous != event:
                return _receipt(case_id, "needs_review", "conflict")
            continue
        by_id[event_id] = event
        unique_events.append(event)

    on_hand, available = dict(opening), dict(opening)
    for event in unique_events:
        sku, quantity = event["sku"], event["quantity"]
        if event["type"] == "receipt":
            on_hand[sku] += quantity
            available[sku] += quantity
        elif event["type"] == "ship":
            on_hand[sku] -= quantity
            available[sku] -= quantity
        else:
            available[sku] -= quantity
    if any(value < 0 for value in on_hand.values()) or any(
            value < 0 for value in available.values()):
        return _receipt(case_id, "needs_review", "negative")

    on_hand = {sku: on_hand[sku] for sku in sorted(on_hand)}
    available = {sku: available[sku] for sku in sorted(available)}
    return _receipt(case_id, "completed", "none", on_hand, available)


def _write_json(path: str, value: Dict[str, Any]) -> None:
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary_path = tempfile.mkstemp(prefix=".receipt-", suffix=".json", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(value, handle, ensure_ascii=True, separators=(",", ":"))
            handle.write("\n")
        os.replace(temporary_path, path)
    except BaseException:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise


def main(argv: List[str]) -> int:
    if len(argv) != 3:
        print(f"usage: {argv[0]} INPUT.json OUTPUT.json", file=sys.stderr)
        return 2
    input_path, output_path = argv[1:]
    try:
        with open(input_path, "r", encoding="utf-8") as handle:
            case = json.load(handle)
        receipt = reconcile(case)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        receipt = _receipt("", "failed", "invalid")
        print(f"could not read input: {error}", file=sys.stderr)
    try:
        _write_json(output_path, receipt)
    except OSError as error:
        print(f"could not write output: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
